def main():
    text = API.read_text(encoding="utf-8")
    if MARK in text:
        print("ALREADY")
        return
    if OLD_FN not in text:
        print("ERROR: named event logo function not found")
        sys.exit(1)
    if OLD_RETURN not in text:
        print("ERROR: with-counts return block not found")
        sys.exit(1)
    bak = API.with_name(API.name + ".bak.event_logos." + datetime.now().strftime("%Y%m%d_%H%M%S"))
    shutil.copy2(API, bak)
    print("BACKUP", bak)
    text = text.replace(OLD_FN, NEW_BLOCK.lstrip(), 1)
    text = text.replace(OLD_RETURN, NEW_RETURN, 1)
    API.write_text(text, encoding="utf-8")
    print("SUCCESS", API)

if __name__ == "__main__":
    main()
